def read_axiom_csv(uploaded_file):
    raw = uploaded_file.getvalue()
    text = raw.decode("utf-8-sig", errors="replace")
    rows = list(csv.reader(io.StringIO(text)))
    if not rows:
        raise ValueError("Fichier CSV vide.")

    # Prend la ligne la plus longue, comme dans les exports AXIOM habituels.
    row = max(rows, key=len)
    if len(row) <= 3:
        raise ValueError("Format AXIOM non reconnu : moins de 4 colonnes.")

    vals = []
    for v in row[3:]:
        s = str(v).strip().replace(",", ".")
        if s:
            vals.append(float(s))

    if not vals:
        raise ValueError("Aucune valeur numérique trouvée après les 3 premières colonnes.")

    return np.asarray(vals, dtype=float)


def reconstruct_axiom(values, step_m):
    """
    Reconstruction utilisée pour les exports AXIOM :
    premier point à 0, puis cumul à partir de la 2e valeur.
    """
    values = np.asarray(values, dtype=float)
    z = np.zeros(len(values), dtype=float)
    if len(values) > 1:
        z[1:] = np.cumsum(values[1:])
    x = np.arange(len(values), dtype=float) * step_m
    return x, z


def interp_z(x, z, xp):
    return float(np.interp(xp, x, z))


def analyze_rule(x, z, rule_length_m, tolerance_mm, step_m):
    if len(x) < 2:
        return pd.DataFrame(), {}

    total_len = float(x[-1] - x[0])

    empty_stats = {
        "distance_m": total_len,
        "n_points": int(len(x)),
        "n_rules": 0,
        "n_conform": 0,
        "n_nonconform": 0,
        "pct_conform": np.nan,
        "pct_nonconform": np.nan,
        "max_abs_mm": np.nan,
        "max_signed_mm": np.nan,
        "max_type": "",
    }

    if total_len + 1e-9 < rule_length_m:
        return pd.DataFrame(), empty_stats

    starts = []
    s = float(x[0])
    last_start = float(x[-1] - rule_length_m)

    while s <= last_start + 1e-9:
        starts.append(round(s, 10))
        s += step_m

    rows = []

    for idx, x0 in enumerate(starts, start=1):
        x1 = x0 + rule_length_m
        z0 = interp_z(x, z, x0)
        z1 = interp_z(x, z, x1)

        mask = (x > x0 + 1e-9) & (x < x1 - 1e-9)
        xs = np.concatenate([[x0], x[mask], [x1]])
        zs = np.concatenate([[z0], z[mask], [z1]])

        ref = z0 + (z1 - z0) * ((xs - x0) / rule_length_m)
        dev = zs - ref

        imax = int(np.argmax(np.abs(dev)))
        signed = float(dev[imax])
        absmax = abs(signed)

        rows.append({
            "Regle": idx,
            "Debut_m": x0,
            "Fin_m": x1,
            "Centre_m": x0 + rule_length_m / 2.0,
            "Position_defaut_m": float(xs[imax]),
            "Defaut_mm": signed,
            "Defaut_abs_mm": absmax,
            "Type": "Bosse" if signed > 0 else ("Creux" if signed < 0 else "RAS"),
            "Conforme": absmax <= tolerance_mm + 1e-9,
        })

    df = pd.DataFrame(rows)
    if df.empty:
        return df, empty_stats

    n_conf = int(df["Conforme"].sum())
    n_all = int(len(df))
    n_non = n_all - n_conf

    idx_max = int(df["Defaut_abs_mm"].idxmax())
    r = df.loc[idx_max]

    stats = {
        "distance_m": total_len,
        "n_points": int(len(x)),
        "n_rules": n_all,
        "n_conform": n_conf,
        "n_nonconform": n_non,
        "pct_conform": 100.0 * n_conf / n_all if n_all else np.nan,
        "pct_nonconform": 100.0 * n_non / n_all if n_all else np.nan,
        "max_abs_mm": float(r["Defaut_abs_mm"]),
        "max_signed_mm": float(r["Defaut_mm"]),
        "max_type": str(r["Type"]),
    }
    return df, stats


def make_run_chart(run_name, direction, rules_df, tolerance_mm, rule_length_m):
    fig, ax = plt.subplots(figsize=(9.2, 5.8))

    if rules_df.empty:
        ax.text(
            0.5, 0.5,
            "Longueur insuffisante pour simuler la règle",
            ha="center", va="center", transform=ax.transAxes, fontsize=14
        )
        ax.set_axis_off()
    else:
        xx = rules_df["Centre_m"].to_numpy() * 1000.0
        yy = rules_df["Defaut_mm"].to_numpy()
        conform = rules_df["Conforme"].to_numpy(dtype=bool)

        # Courbe générale en bleu.
        ax.plot(xx, yy, linewidth=1.7, color="#154A91", zorder=2)

        # Dépassements au-dessus de la tolérance : portion de courbe en rouge
        # + remplissage entre la courbe et la limite.
        above = yy > tolerance_mm
        if np.any(above):
            y_above = np.where(above, yy, np.nan)
            ax.plot(xx, y_above, linewidth=2.1, color=RED, zorder=4)
            ax.fill_between(xx, tolerance_mm, yy, where=above, color=RED, alpha=0.22, interpolate=True, zorder=3)

        # Dépassements en dessous de la tolérance négative.
        below = yy < -tolerance_mm
        if np.any(below):
            y_below = np.where(below, yy, np.nan)
            ax.plot(xx, y_below, linewidth=2.1, color=RED, zorder=4)
            ax.fill_between(xx, -tolerance_mm, yy, where=below, color=RED, alpha=0.22, interpolate=True, zorder=3)

        # Points hors tolérance mis en évidence.
        bad = ~conform
        if bad.any():
            ax.scatter(xx[bad], yy[bad], s=34, color=RED, zorder=5)

        ax.axhline(tolerance_mm, linewidth=1.4, color=RED, label=f"Limite ± {tolerance_mm:g} mm")
        ax.axhline(-tolerance_mm, linewidth=1.4, color=RED)
        ax.axhline(0, linewidth=0.7, color="#555555")

        max_abs = max(float(np.max(np.abs(yy))) if len(yy) else 0.0, float(tolerance_mm))
        ylim = max(15.0, math.ceil((max_abs + 2.0) / 5.0) * 5.0)
        ax.set_ylim(-ylim, ylim)

        xmax = max(xx) if len(xx) else rule_length_m * 1000
        ax.set_xlim(0, max(1000.0, math.ceil(xmax / 3000.0) * 3000.0))
        ax.set_xlabel(f"Position règle {rule_length_m:g} m (mm)", fontsize=12)
        ax.set_ylabel("Écart creux / bosse (mm)", fontsize=12)
        ax.tick_params(axis="both", labelsize=10)
        ax.grid(True, alpha=0.25)
        ax.legend(loc="lower right", fontsize=10)

    fig.tight_layout()
    bio = io.BytesIO()
    fig.savefig(bio, format="png", dpi=180, bbox_inches="tight", facecolor="white")
    bio.seek(0)
    plt.close(fig)
    return bio


def draw_logo(c, x, y, w, h):
    c.drawImage(ImageReader(io.BytesIO(LOGO_BYTES)), x, y, w, h, preserveAspectRatio=True, mask="auto")


def draw_border(c, width, height):
    c.setStrokeColor(HexColor("#6D9DC9"))
    c.setLineWidth(1.0)
    c.rect(10, 10, width - 20, height - 20)


def fit_text(c, text, x, y, max_width, font_name="Helvetica-Bold", max_size=14, min_size=8):
    size = max_size
    while size > min_size and c.stringWidth(str(text), font_name, size) > max_width:
        size -= 0.5
    c.setFont(font_name, size)
    c.drawString(x, y, str(text))


