    c.setStrokeColor(HexColor("#777777"))
    c.setFillColor(colors.black)
    c.setFont("Helvetica", 11)

    c.drawString(35, y + 32, "Effectué par :")
    c.line(125, y + 30, 450, y + 30)
    c.drawString(480, y + 32, "Date :")
    c.line(525, y + 30, width - 35, y + 30)

    c.drawString(35, y + 4, "Vérifié par :")
    c.line(125, y + 2, 450, y + 2)
    c.drawString(480, y + 4, "Date :")
    c.line(525, y + 2, width - 35, y + 2)

